function portfolio(lots){ // lots: [{qty, price}]
  var qty=0, cost=0;
  for(var i=0;i<lots.length;i++){ var L=lots[i]; if(!L) continue; var q=+L.qty||0, p=+L.price||0; qty+=q; cost+=q*p; }
  var avg= qty>0 ? cost/qty : 0;
  return {qty:qty, cost:cost, avg:avg};
}
function pnl(lots, currentPrice){
  var p=portfolio(lots); var mv=p.qty*currentPrice;
  var profit=mv-p.cost;
  return {qty:p.qty, cost:p.cost, avg:p.avg, marketValue:mv, pnl:profit, pnlPct: p.cost>0? profit/p.cost*100 : 0};
}
var EXPORTS={portfolio:portfolio, pnl:pnl};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CryptoPnlForgePure = EXPORTS; }
